-- Step 4 of the Nightbane extraction plan (apps/character-creator/docs/surveys/nightbane-core.md):
-- Modern firearms: pistols, revolvers, sub-machineguns, rifles, shotguns. Printed 211-217. 51 rows.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzzzzzzzzz-nb-gear-b-modern-firearms.sql
--
-- D4 (#1126): every item in the equipment chapter is its own `nightbane` row, on
-- Nate's word, read off the Nightbane pages rather than shared with Heroes Unlimited's
-- rows for the near-identical chapter. HU's scripts (add-hu-gear-*.sql) are the
-- PRECEDENT for shape - names, where a combined entry splits into priced rows, which
-- column a number goes in - and each row here was diffed against its HU counterpart
-- to catch misreads. Where the two books disagree, this file holds what Nightbane
-- prints; the PR lists every disagreement and its evidence.
--
-- Slugs are the name plus `-nb`, so no Nightbane row can collide with a row of
-- another game. `cost` is dollars, a range's low end; NULL where the page prints no
-- price, with any printed wording in cost_note. Citations are printed folios
-- (cache page = folio + 1).



-- Read the result back. This batch asserts its OWN rows and nothing else.
SELECT 'all 51 rows of this script are in, as nightbane' AS assertion, count(*) AS got, 51 AS want
  FROM gear WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%'
   AND slug IN ('browning-gp-35-nb', '7-65mm-140-double-action-fn-nb', 'barracuda-fn-revolver-nb', 'brigadier-nb', '7-65mm-model-61-skorpion-nb', 'erma-olympia-nb', 'erma-kgp-68-nb', '7-65mm-pp-walther-nb', '38-special-mauser-revolver-nb', 'parabellum-mauser-nb', '9mm-model-p5-walther-nb', '9mm-model-951r-semi-p-full-auto-beretta-nb', '38-trident-super-4-renato-gamba-revolver-nb', '9mm-wz-63-pm-63-machine-pistol-nb', '38-special-model-960-astra-revolver-nb', 'hammerli-model-208-nb', 'p210-5-p-9mm-model-49-sig-nb', 'p230-sig-sauer-nb', '7-62mm-tt-33-tokarev-nb', '38-no-2-pistol-revolver-nb', '38-special-nb', 'auto-mag-nb', 'harrington-richardson-defender-revolver-nb', '45-colt-nb', '45-model-15-general-officers-nb', '38-service-six-ruger-revolver-nb', '9mm-md1-and-md-1a1-imbel-nb', '9mm-c1-nb', '9mm-mp5-heckler-koch-nb', '9mm-uzi-nb', '9mm-mini-uzi-nb', '9mm-model-12-beretta-nb', '45-thompson-m1-nb', 'ingram-model-10-nb', '7-62mm-model-30-11-sniping-fn-rifle-nb', '7-62mm-c1a1-modified-rifle-nb', 'model-98-mauser-nb', 'wa-2000-walther-sniping-rifle-nb', '7-62mm-g3-heckler-koch-nb', '7-62mm-sar-galil-assault-rifle-nb', '7-62mm-galil-sniping-rifle-nb', '7-62mm-ak-47-nb', '7-62mm-dragunov-sniper-svd-nb', '5-56mm-ar-180-scs-sterling-armalite-nb', '5-56mm-m16-m16a1-nb', 'mg-springfield-armory-survival-gun-nb', '12-gauge-rs-200-beretta-shotgun-nb', 'model-12-spas-franchi-shotgun-nb', 'model-37m-ithaca-shotgun-nb', 'stakeout-ithaca-shotgun-nb', 'model-3000-police-smith-wesson-shotgun-nb');

SELECT 'every one has a description' AS assertion, count(*) AS got, 51 AS want
  FROM gear WHERE system = 'nightbane' AND length(description) > 0
   AND slug IN ('browning-gp-35-nb', '7-65mm-140-double-action-fn-nb', 'barracuda-fn-revolver-nb', 'brigadier-nb', '7-65mm-model-61-skorpion-nb', 'erma-olympia-nb', 'erma-kgp-68-nb', '7-65mm-pp-walther-nb', '38-special-mauser-revolver-nb', 'parabellum-mauser-nb', '9mm-model-p5-walther-nb', '9mm-model-951r-semi-p-full-auto-beretta-nb', '38-trident-super-4-renato-gamba-revolver-nb', '9mm-wz-63-pm-63-machine-pistol-nb', '38-special-model-960-astra-revolver-nb', 'hammerli-model-208-nb', 'p210-5-p-9mm-model-49-sig-nb', 'p230-sig-sauer-nb', '7-62mm-tt-33-tokarev-nb', '38-no-2-pistol-revolver-nb', '38-special-nb', 'auto-mag-nb', 'harrington-richardson-defender-revolver-nb', '45-colt-nb', '45-model-15-general-officers-nb', '38-service-six-ruger-revolver-nb', '9mm-md1-and-md-1a1-imbel-nb', '9mm-c1-nb', '9mm-mp5-heckler-koch-nb', '9mm-uzi-nb', '9mm-mini-uzi-nb', '9mm-model-12-beretta-nb', '45-thompson-m1-nb', 'ingram-model-10-nb', '7-62mm-model-30-11-sniping-fn-rifle-nb', '7-62mm-c1a1-modified-rifle-nb', 'model-98-mauser-nb', 'wa-2000-walther-sniping-rifle-nb', '7-62mm-g3-heckler-koch-nb', '7-62mm-sar-galil-assault-rifle-nb', '7-62mm-galil-sniping-rifle-nb', '7-62mm-ak-47-nb', '7-62mm-dragunov-sniper-svd-nb', '5-56mm-ar-180-scs-sterling-armalite-nb', '5-56mm-m16-m16a1-nb', 'mg-springfield-armory-survival-gun-nb', '12-gauge-rs-200-beretta-shotgun-nb', 'model-12-spas-franchi-shotgun-nb', 'model-37m-ithaca-shotgun-nb', 'stakeout-ithaca-shotgun-nb', 'model-3000-police-smith-wesson-shotgun-nb');

