  ('5-56mm-m16-m16a1-nb', '5.56mm M16 & M16A1', 'nightbane', 'weapon', 6.8, 675, NULL, '4D6', 0, '1320ft (400m)', '20 or 30 round box mag.', NULL, NULL, NULL, 'Country: U.S.. Cartridge: 5.56mm. Barrel length: 508mm (990mm). Muzzle velocity: 1000m/s.', 'Nightbane RPG p.216'),
  ('mg-springfield-armory-survival-gun-nb', 'MG Springfield Armory Survival Gun', 'nightbane', 'weapon', 3.2, 700, NULL, '2D6', 0, '1200ft (366m)', 'single shot', NULL, NULL, NULL, 'Country: U.S.. Cartridge: .22 long rifle rim-fire. Barrel length: 457mm (80cm). Muzzle velocity: 300m/s.', 'Nightbane RPG p.217'),
  ('12-gauge-rs-200-beretta-shotgun-nb', '12 Gauge RS 200 Beretta Shotgun', 'nightbane', 'weapon', 6.6, 450, NULL, '4D6 for Buckshot (scatter), 5D6 for solid slug', 0, '100ft (30m)', '5-6 round, pump operated', NULL, NULL, NULL, 'Country: Italy. Calibre: 12 gauge. Barrel length: 520mm (1030mm). Type: manual repeating, pump action. Printed weight is approx. 3kg. Damage and range are not in the entry itself: the note heading the shotgun list on printed 217 says they apply to ALL shotguns - Approx. Effective Range 100ft (30m); Damage 4D6 for buckshot (scatter), 5D6 for solid slug.', 'Nightbane RPG p.217'),
  ('model-12-spas-franchi-shotgun-nb', 'Model 12 SPAS Franchi Shotgun', 'nightbane', 'weapon', 7.1, 550, NULL, '4D6 for Buckshot (scatter), 5D6 for solid slug', 0, '100ft (30m)', 'magazine', NULL, NULL, NULL, 'Country: Italy. Cartridge: 12 bore. Barrel length: 500mm (900mm). Type: gas, semi-auto or hand pump. Damage and range are not in the entry itself: the note heading the shotgun list on printed 217 says they apply to ALL shotguns - Approx. Effective Range 100ft (30m); Damage 4D6 for buckshot (scatter), 5D6 for solid slug.', 'Nightbane RPG p.217'),
  ('model-37m-ithaca-shotgun-nb', 'Model 37M Ithaca Shotgun', 'nightbane', 'weapon', 3.5, 380, NULL, '4D6 for Buckshot (scatter), 5D6 for solid slug', 0, '100ft (30m)', '5 or 8 round tubular mag.', NULL, NULL, NULL, 'Country: U.S.. Calibre: 12 gauge. Barrel length: 336mm. Type: Slide action repeater. Printed weight is TWO figures, (20 gauge) 1.58kg and (12 gauge) 2.26kg; the lower is stored. Damage and range are not in the entry itself: the note heading the shotgun list on printed 217 says they apply to ALL shotguns - Approx. Effective Range 100ft (30m); Damage 4D6 for buckshot (scatter), 5D6 for solid slug.', 'Nightbane RPG p.217'),
  ('stakeout-ithaca-shotgun-nb', 'Stakeout Ithaca Shotgun', 'nightbane', 'weapon', 3.5, 380, NULL, '4D6 for Buckshot (scatter), 5D6 for solid slug', 0, '100ft (30m)', '5 round tubular mag.', NULL, NULL, NULL, 'Country: U.S.. Calibre: 20 or 12 gauge. Barrel length: 336mm. Type: Slide action repeater. Printed weight is TWO figures, (20 gauge) 1.58kg and (12 gauge) 2.26kg; the lower is stored. Damage and range are not in the entry itself: the note heading the shotgun list on printed 217 says they apply to ALL shotguns - Approx. Effective Range 100ft (30m); Damage 4D6 for buckshot (scatter), 5D6 for solid slug.', 'Nightbane RPG p.217'),
  ('model-3000-police-smith-wesson-shotgun-nb', 'Model 3000 Police Smith & Wesson Shotgun', 'nightbane', 'weapon', 6.7, 900, NULL, '4D6 for Buckshot (scatter), 5D6 for solid slug', 0, '100ft (30m)', 'Single shot', NULL, NULL, NULL, 'Country: U.S.. Calibre: 12 gauge. Barrel length: 458mm (978mm). Damage and range are not in the entry itself: the note heading the shotgun list on printed 217 says they apply to ALL shotguns - Approx. Effective Range 100ft (30m); Damage 4D6 for buckshot (scatter), 5D6 for solid slug.', 'Nightbane RPG p.217');
